interface PricingStrategy {
  getBasePrice(tier: 'premium' | 'enterprise'): number;
  getTaxRate(): number;
  getProcessingFee(): number;
}

class StandardPricingStrategy implements PricingStrategy {
  private readonly PRICING = {
    premium: 9.99,
    enterprise: 49.99
  } as const;

  private readonly TAX_RATE = 0.08;
  private readonly PROCESSING_FEE = 0.029;

  getBasePrice(tier: 'premium' | 'enterprise'): number {
    return this.PRICING[tier];
  }

  getTaxRate(): number {
    return this.TAX_RATE;
  }

  getProcessingFee(): number {
    return this.PROCESSING_FEE;
  }
}

class PriceCalculator {
  constructor(private strategy: PricingStrategy = new StandardPricingStrategy()) {}

  calculate(tier: 'premium' | 'enterprise'): number {
    const basePrice = this.strategy.getBasePrice(tier);
    const tax = basePrice * this.strategy.getTaxRate();
    const fee = basePrice * this.strategy.getProcessingFee();
    return basePrice + tax + fee;
  }
}

