suggestions.after:
interface PaymentSuccess {
  success: true;
  transactionId: string;
  subscription: Subscription;
}

interface PaymentFailure {
  success: false;
  error: string;
  code: 'INVALID_PAYMENT' | 'INSUFFICIENT_FUNDS' | 'CHARGE_FAILED' | 'UPGRADE_FAILED';
}

type PaymentProcessResult = PaymentSuccess | PaymentFailure;

export async function processPremiumPayment(
  userId: string,
  payment: PaymentDetails,
  tier: 'premium' | 'enterprise'
): Promise<PaymentProcessResult> {
  if (!validatePaymentDetails(payment)) {
    return {
      success: false,
      error: 'Invalid payment details',
      code: 'INVALID_PAYMENT'
    };
  }

  const amount = calculateSubscriptionPrice(tier);
  if (payment.amount < amount) {
    return {
      success: false,
      error: `Insufficient payment amount. Required: ${amount}, Provided: ${payment.amount}`,
      code: 'INSUFFICIENT_FUNDS'
    };
  }

  const paymentResult = await chargeCard(payment, amount);
  if (!paymentResult.success) {
    return {
      success: false,
      error: paymentResult.error || 'Payment processing failed',
      code: 'CHARGE_FAILED'
    };
  }

  try {
    await upgradeUserSubscription(userId, tier);
    const subscription = await getUserSubscription(userId);

    return {
      success: true,
      transactionId: paymentResult.transactionId!,
      subscription: subscription!
    };
  } catch (error) {
    return {
      success: false,
      error: 'Failed to upgrade subscription',
      code: 'UPGRADE_FAILED'
    };
  }
}

